#!/usr/bin/env node
import { Command } from "commander";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
const __dirname = join(fileURLToPath(import.meta.url), "..");
const program = new Command();
program
    .name("opencode-claude-mem")
    .description("opencode plugin for claude-mem - shared session memory")
    .version("0.2.0");
program
    .command("install")
    .description("Install plugin globally and link to opencode")
    .option("-g, --global", "Install globally with npm", true)
    .option("-l, --local", "Install from local package (dev mode)", false)
    .option("--skip-link", "Skip linking to opencode config")
    .action(async (options) => {
    const { execa } = await import("execa");
    const { homedir } = await import("node:os");
    const { join, resolve } = await import("node:path");
    const { existsSync, readFileSync } = await import("node:fs");
    console.log("📦 Installing opencode-claude-mem...");
    try {
        const pkgPath = resolve(__dirname, "..", "package.json");
        const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
        if (options.local) {
            console.log(`   Local install: ${pkg.name}@${pkg.version}`);
            console.log("   Running: npm link");
            await execa("npm", ["link"], { cwd: resolve(__dirname, ".."), stdio: "inherit" });
            console.log("✅ Local link complete");
        }
        else if (options.global) {
            console.log("   Running: npm install -g opencode-claude-mem");
            await execa("npm", ["install", "-g", "opencode-claude-mem"], { stdio: "inherit" });
            console.log("✅ Global install complete");
        }
        else {
            console.log(`   Local package: ${pkg.name}@${pkg.version}`);
            console.log("   Use -g for global install or -l for local dev link");
        }
        if (!options.skipLink) {
            console.log("🔗 Linking to opencode config...");
            const configPath = join(homedir(), ".config", "opencode", "opencode.jsonc");
            const pluginPath = options.local ? resolve(__dirname, "..") : "opencode-claude-mem";
            if (existsSync(configPath)) {
                const config = JSON.parse(readFileSync(configPath, "utf8"));
                config.plugin = config.plugin || [];
                config.plugin = config.plugin.filter((p) => Array.isArray(p) ? p[0] !== pluginPath : p !== pluginPath);
                config.plugin.push([pluginPath, {}]);
                writeFileSync(configPath, JSON.stringify(config, null, 2));
                console.log(`✅ Linked to ${configPath}`);
            }
            else {
                console.log(`⚠️  Config not found at ${configPath}`);
                console.log("   Run 'opencode-claude-mem link' manually after opencode creates config");
            }
        }
        console.log("\n🎉 Done! Restart opencode to load the plugin.");
        console.log("   Verify with: opencode-claude-mem status");
    }
    catch (err) {
        console.error("❌ Install failed:", err.message);
        console.log("\n💡 Manual fallback:");
        console.log("   npm install -g opencode-claude-mem");
        console.log("   opencode-claude-mem link");
        process.exit(1);
    }
});
program
    .command("link")
    .description("Link plugin to opencode config")
    .option("-c, --config <path>", "opencode config path", join(homedir(), ".config", "opencode", "opencode.jsonc"))
    .action((options) => {
    const configPath = resolve(options.config);
    const pluginPath = resolve(__dirname, "..");
    if (!existsSync(configPath)) {
        console.error(`❌ Config not found: ${configPath}`);
        process.exit(1);
    }
    const config = JSON.parse(readFileSync(configPath, "utf8"));
    config.plugin = config.plugin || [];
    // Remove existing entry
    config.plugin = config.plugin.filter((p) => Array.isArray(p) ? p[0] !== pluginPath : p !== pluginPath);
    // Add new entry
    config.plugin.push([pluginPath, {}]);
    writeFileSync(configPath, JSON.stringify(config, null, 2));
    console.log(`✅ Linked to ${configPath}`);
    console.log("🔄 Restart opencode to load plugin");
});
program
    .command("unlink")
    .description("Remove plugin from opencode config")
    .option("-c, --config <path>", "opencode config path", join(homedir(), ".config", "opencode", "opencode.jsonc"))
    .action((options) => {
    const configPath = resolve(options.config);
    const pluginPath = resolve(__dirname, "..");
    if (!existsSync(configPath)) {
        console.error(`❌ Config not found: ${configPath}`);
        process.exit(1);
    }
    const config = JSON.parse(readFileSync(configPath, "utf8"));
    config.plugin = config.plugin?.filter((p) => Array.isArray(p) ? p[0] !== pluginPath : p !== pluginPath) || [];
    writeFileSync(configPath, JSON.stringify(config, null, 2));
    console.log(`✅ Unlinked from ${configPath}`);
});
program
    .command("status")
    .description("Check plugin and worker status")
    .option("-u, --url <url>", "Worker URL", "http://127.0.0.1:37700")
    .action(async (options) => {
    console.log("🔍 Checking status...");
    console.log(`   Worker URL: ${options.url}`);
    try {
        const res = await fetch(`${options.url}/health`);
        if (res.ok) {
            console.log("✅ Worker: RUNNING");
        }
        else {
            console.log(`⚠️  Worker: HTTP ${res.status}`);
        }
    }
    catch {
        console.log("❌ Worker: NOT RUNNING");
        console.log("   Start with: claude-mem worker start");
    }
    const configPath = join(homedir(), ".config", "opencode", "opencode.jsonc");
    if (existsSync(configPath)) {
        const config = JSON.parse(readFileSync(configPath, "utf8"));
        const pluginPath = resolve(__dirname, "..");
        const linked = config.plugin?.some((p) => Array.isArray(p) && (p[0] === pluginPath || p[0].includes("opencode-claude-mem")));
        console.log(linked ? "✅ Plugin: LINKED" : "❌ Plugin: NOT LINKED");
    }
    else {
        console.log("❌ Plugin: NO CONFIG");
    }
});
program
    .command("session")
    .description("Show current session info")
    .action(() => {
    console.log("📋 Session info (requires running opencode session)");
    console.log("   Run this inside an opencode session to see details");
});
program
    .command("clear-cache")
    .description("Clear plugin context cache")
    .action(() => {
    console.log("🧹 Cache cleared (restart opencode to take effect)");
});
program.parse();

import { homedir } from "node:os";
import { join } from "node:path";
import { readFileSync, existsSync } from "node:fs";
import { randomUUID } from "node:crypto";
// ---------------------------------------------------------------------------
// Config Resolution
// ---------------------------------------------------------------------------
export function readClaudeMemSettings() {
    const dataDir = process.env.CLAUDE_MEM_DATA_DIR || join(homedir(), ".claude-mem");
    const settingsPath = join(dataDir, "settings.json");
    try {
        if (existsSync(settingsPath)) {
            const doc = JSON.parse(readFileSync(settingsPath, "utf8").replace(/^\uFEFF/, ""));
            const env = doc?.env;
            const nested = env !== null && typeof env === "object" && !Array.isArray(env)
                && Object.keys(env).some(key => key.startsWith("CLAUDE_MEM_"));
            return nested ? env : (doc ?? {});
        }
    }
    catch { }
    return {};
}
export function resolveWorkerUrl(config) {
    // Priority: plugin config > env > settings.json > default
    if (config.workerUrl)
        return config.workerUrl;
    const envUrl = process.env.CLAUDE_MEM_WORKER_URL;
    if (envUrl)
        return envUrl;
    const settings = readClaudeMemSettings();
    const host = process.env.CLAUDE_MEM_WORKER_HOST || settings.CLAUDE_MEM_WORKER_HOST || "127.0.0.1";
    const port = process.env.CLAUDE_MEM_WORKER_PORT || settings.CLAUDE_MEM_WORKER_PORT || "37700";
    const urlHost = host.includes(":") && !host.startsWith("[") ? `[${host}]` : host;
    return `http://${urlHost}:${port}`;
}
function getConfig(config) {
    return {
        workerUrl: resolveWorkerUrl(config ?? {}),
        contextCacheMs: config?.contextCacheMs ?? 60_000,
        maxToolResponseLen: config?.maxToolResponseLen ?? 1000,
        circuitBreakerThreshold: config?.circuitBreakerThreshold ?? 3,
        circuitBreakerTimeoutMs: config?.circuitBreakerTimeoutMs ?? 30_000,
    };
}
// ---------------------------------------------------------------------------
// Circuit Breaker
// ---------------------------------------------------------------------------
class CircuitBreaker {
    tripCount = 0;
    openUntil = 0;
    threshold;
    timeout;
    constructor(threshold, timeout) {
        this.threshold = threshold;
        this.timeout = timeout;
    }
    isOpen() {
        return Date.now() < this.openUntil;
    }
    recordSuccess() {
        this.tripCount = 0;
        this.openUntil = 0;
    }
    recordFailure() {
        this.tripCount++;
        if (this.tripCount >= this.threshold) {
            this.openUntil = Date.now() + this.timeout;
            this.tripCount = 0;
        }
    }
}
// ---------------------------------------------------------------------------
// HTTP Client
// ---------------------------------------------------------------------------
async function request(url, path, init = {}) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5_000);
    try {
        const r = await fetch(`${url}${path}`, {
            ...init,
            signal: controller.signal
        });
        if (!r.ok)
            throw new Error(`${path} ${r.status}`);
        return r;
    }
    finally {
        clearTimeout(timeout);
    }
}
async function postJson(url, path, body) {
    return request(url, path, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
    });
}
async function post(url, path, body) {
    await postJson(url, path, body);
}
// ---------------------------------------------------------------------------
// Session Management
// ---------------------------------------------------------------------------
let session;
let ctxCache = null;
let lastAssistant = "";
let breaker;
let cfg;
function newSession() {
    session = {
        id: `opencode-${process.pid}-${randomUUID()}`,
        anchored: false,
        excluded: false
    };
    return session;
}
export function textFromContent(content) {
    if (typeof content === "string")
        return content;
    if (Array.isArray(content)) {
        return content
            .map(c => (c && typeof c === "object" && "type" in c && c.type === "text" ? String(c.text ?? "") : ""))
            .join("\n")
            .trim();
    }
    return "";
}
function sendPrompt(target, cwd, prompt) {
    const body = {
        contentSessionId: target.id,
        prompt,
        platformSource: "opencode"
    };
    if (cwd)
        body.cwd = cwd;
    target.lastInit = (target.lastInit ?? Promise.resolve(true)).then(() => recordPrompt(target, body));
}
async function recordPrompt(target, body) {
    if (target.excluded || breaker.isOpen())
        return false;
    try {
        const r = await postJson(cfg.workerUrl, "/api/sessions/init", body);
        const reply = (await r.json());
        breaker.recordSuccess();
        if (reply?.reason === "project_excluded") {
            target.excluded = true;
            return false;
        }
        target.anchored = true;
        return true;
    }
    catch {
        breaker.recordFailure();
        return false;
    }
}
function finalize(target, assistantMessage) {
    if (!target)
        return;
    void Promise.all([target.lastInit ?? Promise.resolve(false), target.observations]).then(() => {
        if (!target.anchored || target.excluded)
            return;
        post(cfg.workerUrl, "/api/sessions/summarize", {
            contentSessionId: target.id,
            last_assistant_message: assistantMessage,
            platformSource: "opencode",
        }).catch(() => breaker.recordFailure());
    });
}
async function recordObservation(target, body) {
    if (target.excluded || breaker.isOpen())
        return;
    try {
        await post(cfg.workerUrl, "/api/sessions/observations", body);
        breaker.recordSuccess();
    }
    catch {
        breaker.recordFailure();
    }
}
async function fetchContext(cwd) {
    if (breaker.isOpen())
        return "";
    try {
        const r = await request(cfg.workerUrl, `/api/context/inject?cwd=${encodeURIComponent(cwd)}&platformSource=opencode`);
        const md = (await r.text()) ?? "";
        breaker.recordSuccess();
        return md;
    }
    catch {
        breaker.recordFailure();
        return "";
    }
}
// ---------------------------------------------------------------------------
// Plugin Factory
// ---------------------------------------------------------------------------
export default async function claudeMemPlugin(_input, options) {
    // Initialize config and breaker
    cfg = getConfig(options);
    breaker = new CircuitBreaker(cfg.circuitBreakerThreshold, cfg.circuitBreakerTimeoutMs);
    // Initialize session
    newSession();
    return {
        // Capture user prompts
        async "chat.message"(input, _output) {
            const prompt = input.parts?.[0]?.text ?? input.message?.content ?? "";
            if (prompt && session) {
                sendPrompt(session, input.sessionID, prompt);
            }
            // Capture assistant responses for session summary
            if (input.message?.role === "assistant") {
                lastAssistant = textFromContent(input.message.content);
            }
        },
        // Record tool observations
        async "tool.execute.after"(input, output) {
            const target = session ?? newSession();
            if (target.excluded)
                return;
            const body = {
                contentSessionId: target.id,
                tool_name: input.tool,
                tool_input: input.args,
                tool_response: output.output?.slice(0, cfg.maxToolResponseLen),
                platformSource: "opencode",
            };
            if (input.sessionID)
                body.cwd = input.sessionID;
            const recorded = target.lastInit ?? Promise.resolve(true);
            target.observations = Promise.all([
                target.observations ?? Promise.resolve(),
                recorded.then(r => r ? recordObservation(target, body) : Promise.resolve())
            ]).then(() => { });
        },
        // Inject context from worker
        async "experimental.chat.system.transform"(_input, output) {
            if (breaker.isOpen())
                return;
            const cwd = process.cwd();
            const now = Date.now();
            // Check cache
            if (!ctxCache || ctxCache.cwd !== cwd || now - ctxCache.at > cfg.contextCacheMs) {
                const md = await fetchContext(cwd);
                if (md.trim()) {
                    ctxCache = { at: now, cwd, md };
                }
                else {
                    ctxCache = null;
                }
            }
            const injected = ctxCache?.md?.trim();
            if (injected) {
                output.system = [...(output.system ?? []), injected];
            }
        },
        // Cleanup on session end
        async dispose() {
            finalize(session, lastAssistant);
        },
    };
}
